// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function testFuzz_property(uint256 amount, uint256 extraAmount) public {
        vm.assume(amount <= VALUE_CAP);
        // Adversarial recording counterparty: it observes incoming calls to c.
        Recorder rec = new Recorder(address(c));
        vm.deal(address(rec), 1 ether);

        // Actor deposits some positive amount so that the subsequent withdraw can occur.
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(this), amount);
        c.deposit{value: amount}();

        // First, have the recorder call withdrawAll. The reference should make exactly one
        // external call (the value transfer to rec). The mutant will additionally send a
        // zero-value call on the same invocation? No: after rec's credit is zeroed, the
        // mutant's guard still passes, so it makes an extra external call.
        // Actually rec.credit() becomes 0 after first withdrawAll, so the mutant makes a
        // second call on the same withdrawAll? Let's re-read the function. It does only one
        // call per withdrawAll. But we can call withdrawAll twice: once with credit, once with
        // zero credit. The reference makes 1 call total, the mutant makes 2.

        // We need c.withdrawAll() to be invoked by rec (msg.sender = rec).
        // c.withdrawAll uses credit[msg.sender], msg.sender.call.
        // So rec must call c.withdrawAll.
        // We can't vm.prank(rec) easily because rec's receive is the call.

        // Let Recorder have a function that calls c.withdrawAll.
        // Recorder needs to deposit too, so credit[rec] > 0.
        // But Recorder is the one calling c.withdrawAll. Recorder can deposit directly.
        // So instead: Recorder receives ether (to deposit). Then calls c.deposit.
        // Then calls c.withdrawAll. Then calls c.withdrawAll again.

        // Recorder's function:
        rec.runTwoWithdrawals();

        // After both withdrawals, the reference must have made exactly ONE external call
        // to rec (the first withdrawal). The mutant makes TWO external calls to rec
        // (the first, and a second zero-value one on the second withdrawAll).
        // However, the Recorder's receive() is what gets called, so we count calls.

        // Important: c sends value to msg.sender = rec via rec.call.
        // Recorder.receive() counts these.
        assertTrue(rec.callCount() == 1);
    }
}

contract Recorder {
    ReentrancyDAO public c;
    uint256 public callCount;

    constructor(address _c) {
        c = ReentrancyDAO(_c);
    }

    receive() external payable {
        callCount++;
    }

    function runTwoWithdrawals() external {
        // deposit 1 wei to get credit
        c.deposit{value: 1 wei}();
        // first withdrawal: credit is 1, reference and mutant both make a call.
        c.withdrawAll();
        // second withdrawal: credit is 0, reference makes no call, mutant makes a call.
        c.withdrawAll();
    }
}
